><?= date_label($sale['created_at']) ?></small></td><td><?= e($sale['product_name']) ?></td><td><strong><?= e($sale['buyer_name']) ?></strong><small><a href="mailto:<?= e($sale['buyer_email']) ?>"><?= e($sale['buyer_email']) ?></a></small></td><td><?= (int)$sale['quantity'] ?></td><td><?= money(cents((string)$sale['subtotal'])) ?></td></tr><?php endforeach; ?></tbody></table><?php if(!$sales): ?><div class="empty-state"><p>Los pedidos de tus piezas aparecerán aquí.</p></div><?php endif; ?></div></section>